import{_ as l,C as e,o as r,c as d,j as t,a as i,E as s,a3 as h}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"坐忘论·敬信","description":"坐忘论第一篇精读：信为道根、敬为德蒂；有形之物尚且难信，何况无形之道；信敬必须落实为勤行。","frontmatter":{"title":"坐忘论·敬信","description":"坐忘论第一篇精读：信为道根、敬为德蒂；有形之物尚且难信，何况无形之道；信敬必须落实为勤行。","category":"guide","aliases":["坐忘论敬信","敬信一","坐忘论精读之二"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/chapter-01.md","filePath":"daoism/daoist-classics/zuowang-lun/chapter-01.md","lastUpdated":1789714390000}'),g={name:"daoism/daoist-classics/zuowang-lun/chapter-01.md"};function c(u,a,b,m,x,k){const p=e("DaoReadingPrelude"),n=e("DaoTextReading"),o=e("DaoKeywordCards");return r(),d("div",null,[a[0]||(a[0]=t("h1",{id:"坐忘论·敬信",tabindex:"-1"},[i("坐忘论·敬信 "),t("a",{class:"header-anchor",href:"#坐忘论·敬信","aria-label":'Permalink to "坐忘论·敬信"'},"​")],-1)),s(p,{title:"信是道之根，敬是德之蒂",summary:"第一篇解决的不是技巧，而是方向：若不信坐忘是修道要门，一遇困难便会退转。但「敬信」不是盲信——它要求认可其价值、尊重其方法、亲自实行，再由实践验证。它同时提前给出了全书的终极境界：内不觉其身，外不知宇宙，与道冥一。",points:[{label:"立根蒂",text:"根深则道可长，蒂固则德可茂。"},{label:"破反例",text:"卞和以玉致刖、伍子以言从诛——形器已著而心绪反迷。"},{label:"归勤行",text:"信、敬之外，还要「加之勤行」，得道方必。"}],hint:"此篇可与《天隐子·神仙一》对读：一篇说人本有灵气，一篇说信敬是修道之根，同是「先正见地」。"}),a[1]||(a[1]=t("h2",{id:"【原典层】原文",tabindex:"-1"},[i("【原典层】原文 "),t("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),a[2]||(a[2]=t("p",null,[t("strong",null,"一、信敬是道德的根蒂")],-1)),s(n,{paragraphs:["夫信者道之根，敬者德之蒂，根深则道可长，蒂固则德可茂。"]}),a[3]||(a[3]=t("p",null,[t("strong",null,"二、有形之物尚且不被相信")],-1)),s(n,{paragraphs:["然则璧耀连城之彩，卞和致刖。言开保国之效，伍子从诛。","斯乃形器著而心绪迷，理事萌而情思忽。","况至道超于色味，真性隔于可欲，而能闻希微以悬信，听罔象而不惑者哉。"]}),a[4]||(a[4]=t("p",null,[t("strong",null,"三、敬信坐忘，勤行得道")],-1)),s(n,{paragraphs:["如人闻坐忘之言，信是修道之要，敬仰尊重，决定无疑者，加之勤行，得道必矣。","故庄云：隳支体，黜聪明，离形去智，同于大通，是谓坐忘。"]}),a[5]||(a[5]=t("p",null,[t("strong",null,"四、坐忘所忘与信不足之患")],-1)),s(n,{paragraphs:["夫坐忘者，何所不忘哉。内不觉其一身，外不知乎宇宙，与道冥一，万虑皆遗。","庄云同于大通，此则言浅而意深。","惑者闻而不信，怀宝求宝，其如之何。","经云：信不足焉，有不信。谓信道之心不足，乃有不信之祸及之，何道之可望乎。"]}),a[6]||(a[6]=t("h2",{id:"【原典层】字词释义",tabindex:"-1"},[i("【原典层】字词释义 "),t("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(o,{items:[{term:"蒂",pinyin:["dì"],meaning:"花蒂。根深蒂固，喻根基牢固——道以信为根，德以敬为蒂。信解决方向，敬解决态度。"},{term:"卞和致刖",pinyin:["biàn","hé","zhì","yuè"],meaning:"事见《韩非子·和氏》：卞和献玉璞，两代楚王听玉工之言以为石，先后刖其双足。喻真实之宝因识见昏昧而不被承认。"},{term:"伍子从诛",pinyin:["wǔ","zǐ","cóng","zhū"],meaning:"伍子胥谏吴王夫差警惕越国，不被采纳，反受赐死，后越果灭吴。与卞和并列，皆谓才器显著而心绪反迷。"},{term:"形器著",pinyin:["xíng","qì","zhù"],meaning:"形器，有具体形态之物；著，显著。谓对象明明可见可验，心却仍然迷惑。"},{term:"理事萌",pinyin:["lǐ","shì","méng"],meaning:"理事，事物中的道理与征验；萌，开始显露。谓事理与征兆已经显现，人却因情感成见而轻忽。"},{term:"希微",pinyin:["xī","wēi"],meaning:"语本《道德经》第十四章：「听之不闻名曰希，搏之不得名曰微」。指大道无声无形、幽隐难见。"},{term:"悬信",pinyin:["xuán","xìn"],meaning:"悬，悬远、尚未亲见。谓虽未直接证得，仍对幽微之道建立坚定信心——这是初学的起步方式，不是终点。"},{term:"罔象",pinyin:["wǎng","xiàng"],meaning:"无形无象、恍惚幽隐、不能以具体形象限定。可与《庄子·天地》「象罔得玄珠」参看。"},{term:"隳支体",pinyin:["huī","zhī","tǐ"],meaning:"隳，消解、放下；支体，四肢身体。谓放下以身体感受、欲望与边界为中心的执著，非伤害身体。今本《庄子》多作「堕肢体」。"},{term:"黜聪明",pinyin:["chù","cōng","míng"],meaning:"黜，退去其主导地位。谓不把感官分辨与智力计算视为通向大道的最高能力，非教人愚昧。"},{term:"离形去智",pinyin:["lí","xíng","qù","zhì"],meaning:"不再执身形为真实固定的自我，不再执分别判断为认识大道的唯一方式。所去者是「执」，不是正常功能。"},{term:"同于大通",pinyin:["tóng","yú","dà","tōng"],meaning:"大通，无所阻隔、与道贯通。「我与万物绝对对立」的执著暂时消融，非谓事实差别消失。"},{term:"冥一",pinyin:["míng","yī"],meaning:"冥，幽深无形，亦有暗合默契之义；一，合而不分。谓在幽深无迹中与道合一，不留外在痕迹，也无「我成功进入合一」的宣告。"},{term:"万虑皆遗",pinyin:["wàn","lǜ","jiē","yí"],meaning:"种种思虑都被放下，不再留藏于心。遗，非暴力消灭，而是放下、不再承载。"},{term:"怀宝求宝",pinyin:["huái","bǎo","qiú","bǎo"],meaning:"怀中本有宝，却向外求宝。宝指人与生俱来的真性、灵明与道性——道不在外，真性原本是自身之宝。"}]}),a[7]||(a[7]=h(`<h2 id="【解读层】精读" tabindex="-1">【解读层】精读 <a class="header-anchor" href="#【解读层】精读" aria-label="Permalink to &quot;【解读层】精读&quot;">​</a></h2><h3 id="一、信是道之根-敬是德之蒂" tabindex="-1">一、信是道之根，敬是德之蒂 <a class="header-anchor" href="#一、信是道之根-敬是德之蒂" aria-label="Permalink to &quot;一、信是道之根，敬是德之蒂&quot;">​</a></h3><p>「信」是信受、确认，不再反复犹疑；「敬」是尊重、慎重，不轻慢、不怠惰。二者各有侧重：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>信如根：使修道有立足之处，不因怀疑而轻易动摇</span></span>
<span class="line"><span>敬如蒂：使道不只停留在观念中，而能落实、结成果实</span></span></code></pre></div><ul><li>「信」解决<strong>方向</strong>问题：我是否真正认定坐忘值得实行？</li><li>「敬」解决<strong>态度</strong>问题：我是否认真、持续地对待已经认定的道路？</li></ul><p>有信而无敬，容易变成口头认同（觉得道理很好，却不肯调整生活）；有敬而无信，则可能只剩形式（恭敬仪式、尊崇权威，却不明白自己为什么修）。<strong>信使方向确定，敬使行动郑重</strong>，二者相合，才算开始真正修道。</p><p>「根深则道可长，蒂固则德可茂」——「可长」「可茂」说明敬信只是<strong>起点</strong>：种子有根不等于已是大树，相信坐忘不等于已经达到坐忘。它也解释了为什么【敬信】之后紧接【断缘】：真正的信敬必须表现为现实生活中的取舍；若一切外缘照旧经营，只说自己信道，根仍没有扎进土里。</p><h3 id="二、有形之物尚且不被相信" tabindex="-1">二、有形之物尚且不被相信 <a class="header-anchor" href="#二、有形之物尚且不被相信" aria-label="Permalink to &quot;二、有形之物尚且不被相信&quot;">​</a></h3><p><strong>卞和献玉</strong>（《韩非子·和氏》）：楚人卞和得玉璞，先后献给厉王、武王，玉工却说是石头，卞和因此两遭刖足。后楚文王命人剖开，果得美玉，即和氏璧。玉是「形器著」的——有具体形体、可以剖开检验、最终能证明价值；即使如此，人仍可能因成见与判断错误而拒绝相信。</p><p><strong>伍子胥进谏</strong>：他多次劝夫差警惕越国、不可因眼前胜利而放过后患，夫差不听谗言反赐其死，后越果灭吴。这是「理事萌」——越国的威胁并非无从预见（勾践忍辱求存、越国暗复国力、吴国连年用兵而疲弊），事情已显端倪，却因骄傲、好胜与个人爱恶而被忽略。</p><table tabindex="0"><thead><tr><th>卞和</th><th>伍子胥</th></tr></thead><tbody><tr><td>献上真玉</td><td>献上忠言</td></tr><tr><td>玉有实际价值</td><td>忠言有实际效用</td></tr><tr><td>世人不能识玉</td><td>吴王不能识忠</td></tr><tr><td>卞和遭刖</td><td>伍子胥遭诛</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>形器已著，却不能识物</span></span>
<span class="line"><span>理事已萌，却不能识机</span></span></code></pre></div><p>二者共同说明：<strong>有形可验、事理可察的真相，人尚且会因迷惑而拒绝；无形无象的大道，自然更难得到信受。</strong></p><p>人不能认识真实，不一定因为真实过于遥远，也可能是因为心已被成见、利害、好恶、对权威的依从、对忠言的排斥所干扰。所以认识问题首先是<strong>心</strong>的问题——这已预告了【真观】的主题：真正的观照，必须建立在欲望减弱、心绪清静的基础上。</p><p>不过本篇并非要求盲目相信他人，也不意味着「无法验证的说法就更该相信」；它诊断的是<strong>认识障碍</strong>：我是否只相信符合自身欲望的东西？是否把不合己意的忠言当成错误？是否把暂时看不到效果，等同于方法没有价值？</p><h3 id="三、至道为何更难相信" tabindex="-1">三、至道为何更难相信 <a class="header-anchor" href="#三、至道为何更难相信" aria-label="Permalink to &quot;三、至道为何更难相信&quot;">​</a></h3><p><strong>「至道超于色味」</strong>——美玉能被眼睛看见，食物能被口舌尝到；大道却不是可以摆在眼前、供感官占有的东西。「超于色味」不是说大道在遥远的另一个世界，而是说：<strong>道不是一个与其他物品并列的感官对象</strong>。人可以看见某种合道的行为，却不能像看见器物一样看见「道自身」。</p><p>这与《道德经》第十四章相应：「视之不见，名曰夷；听之不闻，名曰希；搏之不得，名曰微。」</p><p><strong>「真性隔于可欲」</strong>——不是说真性远离人，而是说真性与通常的欲望机制不在同一方向：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>可欲之物：通过追逐、占有而得</span></span>
<span class="line"><span>真实本性：通过减少遮蔽、停止外驰而显</span></span></code></pre></div><p>欲望的基本结构是「感到缺少 → 把某物当成满足对象 → 努力占有 → 短暂满足后又追下一个」。但真性不是外在物品，不能被「我」占有；修行要做的不是获得一个新对象，而是使不断占有对象的心安静下来。这与总论「将生灭质，求无为道」的批评相连：若仍以追逐可欲之物的心态追逐真性，就把修道变成了另一种占有。</p><p><strong>「闻希微以悬信」</strong>——「希微」语出《道德经》第十四章，成为大道无声无形的代称；「悬信」谓虽未亲证，仍建立坚定信心。初学者尚未亲证，须暂时依据经典的指引、前人的经验、自己对生活困境的反省与初步实践的身心验证：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>最初：闻道而信 → 继而：依信而行 → 再后：由行而知 → 最终：亲自契入</span></span></code></pre></div><p>所以敬信是「根」，不是最后的「果」。</p><p><strong>「听罔象而不惑」</strong>——罔象指无形无象、不能用具体形象限定（可与《庄子·天地》「象罔得玄珠」参看）。世俗事物看得见、尝得到、可以交易，所以容易相信；坐忘之道要求减少欲望、放下占有，初期又难以直接看见成果，所以容易怀疑。敬信不是多余的宗教装饰，而是帮助人跨过**「尚未亲证」的阶段**。</p><h3 id="四、信敬必须落实为勤行" tabindex="-1">四、信敬必须落实为勤行 <a class="header-anchor" href="#四、信敬必须落实为勤行" aria-label="Permalink to &quot;四、信敬必须落实为勤行&quot;">​</a></h3><p>「信是修道之要」中的「信」有明确对象：不是泛泛相信神秘事物，而是相信<strong>坐忘是修道之要</strong>。因为修道的主要障碍正是心神不断向外驰逐（逐声色、名利、毁誉、知识、修行境界、乃至「我将成为怎样的人」）；坐忘不是额外增加一个对象，而是从根本上松开这种逐取活动，所以它触及修道的枢要。</p><p>「敬仰尊重，决定无疑者」——「决定无疑」不等于禁止提问。可以区分两种「疑」：</p><ul><li><strong>有益的审察</strong>：这句话究竟怎样理解？我现在的做法是否过紧？这是清醒安定还是昏沉？——帮助辨别正误。</li><li><strong>使修行无法开始的摇摆</strong>：今天试这个明天换那个；因暂时没有特殊感受便否定方法；一遇杂念便认为自己不能修；永远研究方法却不实际开始。</li></ul><p>「加之勤行，得道必矣」——关键不只是「必矣」，而是「<strong>加之勤行</strong>」：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>闻道 ≠ 得道    信道 ≠ 得道    敬仰 ≠ 得道</span></span>
<span class="line"><span>敬信 + 勤行，才构成实际修道</span></span></code></pre></div><p>这与总论「重道德之名，轻道德之行」直接相接。「勤行」不是追求高强度，而是<strong>长期持续、不随情绪中断</strong>：从断缘、收心等基础做起，念起时觉察并收回，在日常行住坐卧中安养其心。</p><h3 id="五、《庄子》所说的坐忘" tabindex="-1">五、《庄子》所说的坐忘 <a class="header-anchor" href="#五、《庄子》所说的坐忘" aria-label="Permalink to &quot;五、《庄子》所说的坐忘&quot;">​</a></h3><p>书中引「隳支体，黜聪明，离形去智，同于大通，是谓坐忘」，出自<a href="/Dao/daoism/zhuang-zi/chapter-06">《庄子·大宗师》</a>颜回与孔子的对话（今本常见作「堕肢体，黜聪明，离形去知，同于大通，此谓坐忘」，底本作「隳」「智」）。</p><table tabindex="0"><thead><tr><th>语</th><th>所去者</th><th>注意</th></tr></thead><tbody><tr><td><strong>隳支体</strong></td><td>以身体感受、欲望与边界为中心的执著</td><td>非伤害身体——那反而与道教保养性命相冲突；是身体不再占据全部意识中心</td></tr><tr><td><strong>黜聪明</strong></td><td>把感官分辨与智力计算视为通向大道的最高能力</td><td>非教人愚昧；是把智巧从主人位置退下来</td></tr><tr><td><strong>离形去智</strong></td><td>不再执身形为固定自我，不再执分别为唯一认识方式</td><td>所去者是「执」，不是正常功能</td></tr><tr><td><strong>同于大通</strong></td><td>「我与万物绝对对立」的执著</td><td>不是说事实差别消失，而是主体与对象的分立暂时消融</td></tr></tbody></table><p>「黜聪明」所退去的，正是总论批评的「自云智巧」：聪明可以帮助处理事务，也可能不断强化计较、分别、自我证明与名声竞争。而「离形去智」所去的是执，这为《枢翼》的「唯灭动心，不灭照心」预留了空间——<strong>坐忘要去除攀缘智巧，却不消灭清醒觉照</strong>。</p><h3 id="六、坐忘究竟忘什么" tabindex="-1">六、坐忘究竟忘什么 <a class="header-anchor" href="#六、坐忘究竟忘什么" aria-label="Permalink to &quot;六、坐忘究竟忘什么&quot;">​</a></h3><p>「夫坐忘者，何所不忘哉」——这个反问表示坐忘之「忘」是彻底的，可分几层：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>忘外缘：不再反复经营名利、人情和毁誉</span></span>
<span class="line"><span>忘所欲：不再让声色财货占据心神</span></span>
<span class="line"><span>忘形：  身体不再成为自我执著的中心</span></span>
<span class="line"><span>忘智：  不再依赖分别、辩论和机巧把握道</span></span>
<span class="line"><span>忘我：  不再突出一个修道、得道的主体</span></span>
<span class="line"><span>忘忘：  连「我已经忘了什么」的意识也不保留</span></span></code></pre></div><p>最后一层本篇未明说，却与《天隐子》「因存想而得也，因存想而忘也」完全相通。</p><p><strong>「内不觉其一身」</strong>——不是昏迷、麻木、失去身体知觉，也不是故意压制呼吸或感官；而是说在深度安定中，平常异常突出的身体中心感逐渐淡化。静坐时人通常不断觉察（腿是否舒服、姿势是否正确、有没有进步），这些自我监控一旦不断占据注意力，「一身」就仍然鲜明。</p><p><strong>「外不知乎宇宙」</strong>——不是知识丧失，而是外界不再成为攀缘分别的对象：外界仍然存在，但心不再不断把它组织成与「我」有关的欲望与利害网络。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>内不执我，外不逐物 → 我与物的对立暂息 → 与道冥一</span></span></code></pre></div><p><strong>「与道冥一」</strong>——不同于通过概念得出「万物是一」的结论。若只不断告诉自己「我与道合一」，仍有一个「我」、一个「道」、一个「合一」的观念。真正的「冥一」不留外在痕迹：不一定出现奇异景象，不需要向人展示境界，甚至不应执著自己达到某种状态。</p><p><strong>「万虑皆遗」</strong>——放下过去的追悔、未来的筹划、对毁誉的反应、对得失的计算、对修行进度的评判。「遗」不是暴力消灭，而是放下、不再承载。可与《庄子·应帝王》「至人之用心若镜，不将不迎，应而不藏」互相说明：念未起时不主动招引，念已起时不继续追随，事情过去不留藏于心。</p><h3 id="七、言浅而意深-·-怀宝求宝" tabindex="-1">七、言浅而意深 · 怀宝求宝 <a class="header-anchor" href="#七、言浅而意深-·-怀宝求宝" aria-label="Permalink to &quot;七、言浅而意深 · 怀宝求宝&quot;">​</a></h3><p>「同于大通」只有四个字，却至少包含：身体中心感的淡化、感官攀缘的止息、智巧分别的退位、自我意识的松开、内外二分的超越、心神与道的相应。<strong>言浅而意深</strong>——若把「同于大通」变成哲学口号，却不经历断缘、收心、简事、真观、泰定，就仍是总论所批评的「重道德之名，轻道德之行」。</p><p>「惑者闻而不信，怀宝求宝」——「宝」指人与生俱来的真性、灵明与道性：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>人本来禀道而生，真性并未真正失去，只是被欲望与思虑遮蔽</span></span>
<span class="line"><span>      ↓ 若不知道自己有宝，便不断向外求取</span></span>
<span class="line"><span>      ↓ 所得越多，外驰越甚，反而离本有之宝更远</span></span></code></pre></div><p>这与《天隐子·神仙一》「修我灵气，勿为世俗所沦污；遂我自然，勿为邪见所凝滞」高度一致——两书都把修行理解为<strong>返与复</strong>，而不是外在占有。</p><p>但「怀宝求宝」并不意味着不需要老师与经典：本篇本身就在引《庄子》并要求「闻坐忘之言」。老师和经典的作用不是把道性从外面塞进人心，而是指出人本有的根本、揭示遮蔽所在、提供修习次第、帮助辨别偏差。可以比喻为：<strong>经典不是替你制造宝物，而是提醒你不要继续背着宝物向外乞求。</strong></p><h3 id="八、信不足焉-有不信" tabindex="-1">八、信不足焉，有不信 <a class="header-anchor" href="#八、信不足焉-有不信" aria-label="Permalink to &quot;八、信不足焉，有不信&quot;">​</a></h3><p>「信不足焉，有不信」出自《道德经》第十七章（通行本多作「信不足焉，有不信焉」），原章讨论统治者与百姓的关系，本篇转用于个人修道。「不信之祸」不必理解成大道降罚，更适合从修习因果理解：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>信心不足 → 不能决定实行 → 今日修、明日废 → 一遇杂念便退</span></span>
<span class="line"><span>        → 不断更换方法 → 修习始终不能深入</span></span>
<span class="line"><span>        → 最后以「没有效果」证明自己原先的不信</span></span></code></pre></div><p>这是一种自我实现的循环。而且信心不足时，人会不断退回原来的价值尺度：以外在成就衡量修行、期待迅速获得特殊体验、以是否受人认可判断自己、仍用智巧和欲望追逐无为。</p><p>「何道之可望乎」是全篇结尾的反问：道无形无象，修习又必须长期调心；若连第一步的方向都不能确定，后面的七阶便无从谈起。<strong>敬信不是七阶中的一项普通内容，而是贯穿其余六阶的动力。</strong></p><h3 id="引经据典" tabindex="-1">引经据典 <a class="header-anchor" href="#引经据典" aria-label="Permalink to &quot;引经据典&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书中引文／典故</th><th>出处</th><th>作用</th></tr></thead><tbody><tr><td>卞和献玉</td><td>《韩非子·和氏》</td><td>有形而真实的宝物，也可能因识见昏昧而不被相信</td></tr><tr><td>伍子胥进谏</td><td>《史记》等</td><td>事理与征兆已经显现，也可能因情欲、骄傲与谗言而被忽略</td></tr><tr><td>希微</td><td>《道德经》第十四章</td><td>大道超越一般感官对象，初学者须从闻道而信开始</td></tr><tr><td>罔象</td><td>无形无象；参《庄子·天地》「象罔得玄珠」</td><td>大道不能只靠感官、机智与分别把握</td></tr><tr><td>坐忘</td><td><a href="/Dao/daoism/zhuang-zi/chapter-06">《庄子·大宗师》</a></td><td>给出坐忘的根本定义：隳支体、黜聪明、离形去智、同于大通</td></tr><tr><td>信不足焉，有不信</td><td>《道德经》第十七章</td><td>由政治语境转入修道语境，说明无信心便无法长期实行</td></tr></tbody></table><p>逐条的原典语境与考订见<a href="/Dao/daoism/daoist-classics/zuowang-lun/classics">《引经据典》</a>。</p><h3 id="与《天隐子》的对应" tabindex="-1">与《天隐子》的对应 <a class="header-anchor" href="#与《天隐子》的对应" aria-label="Permalink to &quot;与《天隐子》的对应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>《天隐子》</th><th>本篇</th><th>呼应</th></tr></thead><tbody><tr><td>神仙第一（禀得灵气，勿为世俗所沦污）</td><td>怀宝求宝</td><td>道不在外，真性本具；修行是除蔽返本</td></tr><tr><td>易简第二（至道不繁，反对奇诡）</td><td>言浅而意深</td><td>不以语言的复杂程度判断道法高低，贵在实行</td></tr><tr><td>神解八（斋戒谓之信解，无信心则不能解）</td><td>敬信为七阶之首</td><td>都认为没有基本信受，方法便无法落实</td></tr><tr><td>存想六（存我之神，想我之身）</td><td>返照本有之宝</td><td>所求的根本不在外物，而在被遮蔽的自身真性</td></tr><tr><td>坐忘七（遗形忘我，心不动、形都泯）</td><td>隳支体 · 内不觉身</td><td>本篇展开为：隳支体→遗形、黜聪明→去执、与道冥一→同于大通</td></tr></tbody></table><p>《敬信》篇其实已先把全书的终点呈现出来，后面六篇则解释怎样一步步达到。两书安排的差异（《天隐子》以斋戒的实际行动成就「信解」，《坐忘论》先直接立信敬）见<a href="/Dao/daoism/daoist-classics/zuowang-lun/guide#八与天隐子的对应与差异">《全书引读》· 与《天隐子》的对应与差异</a>。</p><h3 id="容易误解的地方" tabindex="-1">容易误解的地方 <a class="header-anchor" href="#容易误解的地方" aria-label="Permalink to &quot;容易误解的地方&quot;">​</a></h3><ol><li><strong>敬信不是盲信</strong>——盲信不许提问、拒绝验证、只凭权威；本篇的敬信有明确对象与实践路径：闻坐忘之言 → 信其为修道之要 → 敬重不轻忽 → 加之勤行 → 在身心变化中逐步体认。</li><li><strong>「决定无疑」不是不能辨别真伪</strong>——《枢翼》明说「虽知诵读其文，仍须辨识真伪」。它指修道方向不再反复动摇，不是取消思考能力。</li><li><strong>「黜聪明」不是反智</strong>——所黜的是以聪明建立优越感、以智巧追逐名利、以辩论代替实行。真正的慧并未被取消，【真观】【泰定】正要讨论智慧的生起。</li><li><strong>「内不觉身，外不知宇宙」不是昏迷</strong>——《枢翼》后来说得明白：「唯灭动心，不灭照心。」坐忘是清醒而不攀缘。</li><li><strong>「万虑皆遗」不是压抑所有思考</strong>——《收心》说「如有时事或法要有疑者，且任思量，令事得济……悟已则止」。问题不在思考本身，而在它是否无休止地盘旋、是否由欲望与毁誉驱动、是否长期占据内心。</li><li><strong>「得道必矣」不是只要相信即可</strong>——完整条件是：信受 + 敬重 + 决定 + 勤行。没有「勤行」，敬信仍只是道德之名。</li></ol><h3 id="现实启示" tabindex="-1">现实启示 <a class="header-anchor" href="#现实启示" aria-label="Permalink to &quot;现实启示&quot;">​</a></h3><ol><li><strong>我信的是「道」，还是修道带来的身份？</strong> ——我是想减少执著，还是想成为一个「懂修行的人」？若修道成了新的身份资本，仍然是在向外求宝。</li><li><strong>我是否因看不到即时效果而轻易放弃？</strong> ——坐忘的变化往往并不戏剧化：对毁誉的反应稍微减弱、杂念起来后更快察觉、不再主动增加无谓事务、能在事情结束后放下。这些不如感官刺激强烈，却更接近真正的「根深蒂固」。</li><li><strong>我所相信的，是否已经变成行动？</strong> ——检验不是口头赞同，而是：是否开始减少不必要的外缘？是否给收心留出稳定时间？是否愿意放下反复证明自己的冲动？</li></ol><h3 id="修行逻辑" tabindex="-1">修行逻辑 <a class="header-anchor" href="#修行逻辑" aria-label="Permalink to &quot;修行逻辑&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>信是道根，敬是德蒂</span></span>
<span class="line"><span>        ↓ 没有信敬，修习不能长久</span></span>
<span class="line"><span>但人心容易受成见和情欲蒙蔽：有形真玉尚不识，有效忠言尚不听</span></span>
<span class="line"><span>        ↓ 何况大道无形无象，真性又不能作为欲望对象去占有</span></span>
<span class="line"><span>所以初学必须闻道而信，敬仰尊重，决定实行</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>坐忘的目标：隳支体、黜聪明、离形去智、同于大通</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>内忘其身，外忘宇宙；与道冥一，万虑皆遗</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>所求之宝本来就在自身——若怀宝求宝、闻而不信，后续修道便无从开始</span></span></code></pre></div><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h3><blockquote><p><strong>修道必须有根，成德必须有蒂；信是其根，敬是其蒂。</strong></p></blockquote><p>但人心容易被情欲与成见蒙蔽：真玉在前而不识，忠言有效而不听，何况大道希微罔象、不能由感官直接占有。因此初学必须经过：闻道 → 信受 → 敬重 → 决定 → 勤行。</p><p>本篇又提前给出全书的终极境界：<strong>内不觉其一身，外不知乎宇宙，与道冥一，万虑皆遗。</strong> 这不是昏沉，也不是失去正常能力，而是不执内身、不逐外境、不以智巧建立自我、不以欲望占有真性。</p><p>而「怀宝求宝」点明了坐忘的返归性质：<strong>大道并非完全在外，真性原本是自身之宝；修行不是向外获得一个新对象，而是停止外求，使本有的灵明不再受到遮蔽。</strong></p><p>下一篇<a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-02">《断缘》</a>将把敬信落实到现实生活：如果信道是真，便必须观察究竟有哪些关系、事务和机心正在持续牵引自己。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/">《坐忘论》总览</a> · <a href="/Dao/daoism/daoist-classics/zuowang-lun/guide">全书引读</a> · <a href="/Dao/daoism/daoist-classics/zuowang-lun/classics">引经据典</a></li><li>上一篇：<a href="/Dao/daoism/daoist-classics/zuowang-lun/preface">序说</a> · 下一篇：<a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-02">断缘二</a></li><li>引文出处：<a href="/Dao/daoism/zhuang-zi/chapter-06">《庄子·大宗师》</a>（坐忘）、《道德经》第十四章（希微）、第十七章（信不足）</li><li>《天隐子》对应：<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-1">神仙一</a>、<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-8">神解八</a>（信解）</li></ul>`,76))])}const f=l(g,[["render",c]]);export{y as __pageData,f as default};
